using System.Globalization;
using System.Runtime.CompilerServices;
using System.Text;
using RecursiveAI.OneOffice.NumberFormats;
using Xunit;

namespace RecursiveAI.OneOffice.Tests.NumberFormats;

/// <summary>
/// Compares the formatter with what desktop Excel (365, build 16.0.20527) answered for a grid of 7,602 format-code and value pairs:
/// the result of <c>TEXT(value, code)</c> and the text a cell with that number format displays (US English settings, 1900 date
/// system). The grid is generated by <c>tools/NumFmtGrid</c>; the answers are in <c>testdata/numfmt/excel-grid.tsv</c>.
/// </summary>
public class NumberFormatExcelGridTests
{
    private static string DataPath([CallerFilePath] string here = "") =>
        Path.Combine(Path.GetDirectoryName(here)!, "..", "..", "..", "testdata", "numfmt", "excel-grid.tsv");

    private static string Unescape(string s)
    {
        if (!s.Contains('\\', StringComparison.Ordinal))
        {
            return s;
        }

        var sb = new StringBuilder(s.Length);
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '\\' && i + 1 < s.Length)
            {
                i++;
                sb.Append(s[i] switch { 't' => '\t', 'n' => '\n', 'r' => '\r', _ => s[i] });
            }
            else
            {
                sb.Append(s[i]);
            }
        }

        return sb.ToString();
    }

    [Fact]
    public void FormatterAgreesWithExcelOverTheGrid()
    {
        string[] lines = File.ReadAllLines(DataPath(), Encoding.UTF8);
        Assert.True(lines.Length > 7000);
        var problems = new List<string>();
        int checkedText = 0, checkedCell = 0;
        var buffer = new char[2048];
        for (int i = 1; i < lines.Length; i++)
        {
            string[] f = lines[i].Split('\t');
            string code = Unescape(f[1]);
            bool isText = f[2] == "t";
            string value = f[3];
            string excelText = Unescape(f[4]);
            string excelCell = Unescape(f[5]);

            if (!NumberFormat.TryParse(code, out NumberFormat? format, out _) || format is null)
            {
                // Excel refuses these codes: TEXT gives #VALUE! and a workbook that holds one does not open.
                Assert.Equal("#VALUE!", excelText);
                continue;
            }

            string ours;
            if (isText)
            {
                ours = format.FormatText(value);
            }
            else
            {
                double v = double.Parse(value, CultureInfo.InvariantCulture);
                FormatResult r = format.TryFormat(v, buffer);
                ours = r.Status == FormatStatus.Ok ? new string(buffer, 0, r.Length) : string.Empty;
                if (r.Status != FormatStatus.Ok)
                {
                    // A value the format cannot show: TEXT gives #VALUE!, and a cell a row of #.
                    Assert.StartsWith("#", excelText, StringComparison.Ordinal);
                    continue;
                }
            }

            // Not differences of the formatter: TEXT refuses results over 255 characters, and converts numeric-looking text to a number first.
            bool textAgrees = excelText == ours
                || (excelText == "#VALUE!" && ours.Length > 255)
                || (isText && double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out _));
            checkedText++;
            if (!textAgrees)
            {
                problems.Add($"#{f[0]} TEXT({value}, {code}): Excel '{excelText}', ours '{ours}'");
            }

            if (excelCell == "<none>")
            {
                continue;
            }

            // A cell shows a row of # when the text does not fit its column, and stretches a * fill over the column.
            bool cellAgrees = excelCell == ours
                || (excelCell.Length > 0 && excelCell.All(c => c == '#') && ours.Length >= 50)
                || (code.Contains('*', StringComparison.Ordinal) && excelCell.Length >= 20);
            checkedCell++;
            if (!cellAgrees)
            {
                problems.Add($"#{f[0]} cell {value} with {code}: Excel '{excelCell}', ours '{ours}'");
            }
        }

        Assert.True(checkedText > 7000 && checkedCell > 7000, $"{checkedText} TEXT cases and {checkedCell} cell cases were compared");
        Assert.True(problems.Count == 0, $"{problems.Count} differences from Excel:\n" + string.Join('\n', problems.Take(25)));
    }

    private static string LocalesPath([CallerFilePath] string here = "") =>
        Path.Combine(Path.GetDirectoryName(here)!, "..", "..", "..", "testdata", "numfmt", "excel-locales.tsv");

    /// <summary>
    /// Month and weekday names, AM/PM and a day-with-month date under a <c>[$-LCID]</c> tag for the locales that real workbooks use
    /// beyond the first thirteen, as Excel displayed them.
    /// </summary>
    [Fact]
    public void LocaleTagsAgreeWithExcelNames()
    {
        string[] lines = File.ReadAllLines(LocalesPath(), Encoding.UTF8);
        Assert.True(lines.Length > 500);
        var problems = new List<string>();
        for (int i = 1; i < lines.Length; i++)
        {
            string[] f = lines[i].Split('\t');
            NumberFormat format = NumberFormat.Parse(f[0]);
            string ours = format.Format(double.Parse(f[1], CultureInfo.InvariantCulture));
            if (ours != f[2])
            {
                problems.Add(f[0] + " " + f[1] + ": ours '" + ours + "', Excel '" + f[2] + "'");
            }
        }

        Assert.True(problems.Count == 0, string.Join('\n', problems.Take(20)));
    }
}
